def clean_pop(row):
    import re
    def norm(x):
        s=str(x).replace('\xa0',' ')
        s=re.sub(r'\s*(Metropolitan Statistical Area|MSA)\s*$','',s,flags=re.I)
        s=re.sub(r'[^A-Za-z0-9]+',' ',s).strip().lower()
        return s
    def num(x):
        try: return float(str(x).replace(',',''))
        except: return None
    return {'key':norm(row['area_raw']),'pop2024':num(row['pop2024']),'pop2020':num(row['pop2020'])}

def clean_theft(row):
    import re
    s=str(row['area_raw']).replace('\xa0',' ')
    s=re.sub(r'\s*(Metropolitan Statistical Area|MSA)\s*$','',s,flags=re.I)
    s=re.sub(r'[^A-Za-z0-9]+',' ',s).strip().lower()
    return {'key':s,'reports':row['reports']}

def interp(row):
    p20=row['pop2020']; p24=row['pop2024']
    p23=None if p20 is None or p24 is None else p20 + (p24-p20)*3/4
    return {**row,'pop2023':p23}
